def test_mixed_fixture_gates_before_ranking_and_caps_shortlist(tmp_path: Path) -> None:
    fixture = SKILL_DIR / "tests" / "fixtures" / "ranking" / "mixed_candidates.json"
    out = tmp_path / "ranking"
    result = runner.invoke(app, ["rank", "--input", str(fixture), "--limit", "8", "--out", str(out)])
    assert result.exit_code == 0, result.output
    receipts = [
        json.loads(line)
        for line in (out / "eligibility-receipts.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    states = {row["candidate_id"]: row["state"] for row in receipts}
    assert states["rank:wny-hybrid"] == "ELIGIBLE_WNY_HYBRID"
    assert states["rank:wny-onsite"] == "ELIGIBLE_WNY_ONSITE"
    assert states["rank:remote"] == "ELIGIBLE_REMOTE"
    assert states["rank:relocation"] == "REJECT_RELOCATION_REQUIRED"
    assert states["rank:ambiguous-location"] == "HUMAN_REVIEW_LOCATION_AMBIGUOUS"
    assert states["rank:unknown-clearance"] == "HUMAN_REVIEW_ELIGIBILITY_UNKNOWN"
    assert states["rank:stale"] == "REJECT_STALE"
    assert states["rank:already-applied"] == "REJECT_DUPLICATE_OR_ALREADY_APPLIED"
    shortlist = json.loads((out / "shortlist.json").read_text(encoding="utf-8"))
    shortlisted_ids = [row["candidate_id"] for row in shortlist]
    assert len(shortlisted_ids) == 8
    assert shortlisted_ids[:3] == ["rank:wny-hybrid", "rank:wny-onsite", "rank:remote"]
    assert "rank:remote-seven" not in shortlisted_ids
    assert not {"rank:relocation", "rank:ambiguous-location", "rank:unknown-clearance"} & set(shortlisted_ids)
    assert json.loads((out / "source-intel-shortlist.json").read_text(encoding="utf-8")) == []


def test_source_intel_cannot_starve_reportable_opportunity_shortlist(tmp_path: Path) -> None:
    candidates = [
        {
            "candidate_id": f"source-intel:{i}",
            "lane": "A",
            "organization": f"LinkedIn Locator {i}",
            "title": "Principal AI Architect",
            "workplace_type": "WNY_HYBRID",
            "location_display": "Buffalo, NY (hybrid)",
            "fit_score": 0.99,
            "relocation_required": False,
            "clearance_required": False,
            "source_provider": "ops_linkedin_authorized_read_only",
            "source_receipt_id": f"receipt:linkedin:{i}",
        }
        for i in range(8)
    ]
    candidates.append(
        {
            "candidate_id": "reportable:lower-score",
            "lane": "A",
            "organization": "Primary ATS Employer",
            "title": "AI Platform Architect",
            "workplace_type": "REMOTE",
            "location_display": "Remote, US",
            "fit_score": 0.5,
            "relocation_required": False,
            "clearance_required": False,
            "source_provider": "greenhouse",
            "source_receipt_id": "receipt:greenhouse",
        }
    )
    fixture = tmp_path / "candidates.json"
    fixture.write_text(json.dumps({"candidates": candidates}), encoding="utf-8")
    out = tmp_path / "ranking"

    result = runner.invoke(app, ["rank", "--input", str(fixture), "--limit", "8", "--out", str(out)])

    assert result.exit_code == 0, result.output
    shortlist = json.loads((out / "shortlist.json").read_text(encoding="utf-8"))
    source_intel = json.loads((out / "source-intel-shortlist.json").read_text(encoding="utf-8"))
    assert [row["candidate_id"] for row in shortlist] == ["reportable:lower-score"]
    assert len(source_intel) == 8
    receipt = json.loads((out / "ranking-receipt.json").read_text(encoding="utf-8"))
    assert receipt["admitted"] == 9
    assert receipt["admitted_opportunities"] == 1
    assert receipt["admitted_source_intel"] == 8
    assert receipt["shortlisted"] == 1
    assert receipt["source_intel_shortlisted"] == 8


def test_source_intel_shortlist_preserves_provider_diversity(tmp_path: Path) -> None:
    candidates = [
        {
            "candidate_id": f"linkedin-source:{i}",
            "lane": "A",
            "organization": f"LinkedIn Locator {i}",
            "title": "Principal AI Architect",
            "workplace_type": "WNY_HYBRID",
            "location_display": "Buffalo, NY (hybrid)",
            "fit_score": 0.99,
            "relocation_required": False,
            "clearance_required": False,
            "source_provider": "ops_linkedin_authorized_read_only",
            "source_receipt_id": f"receipt:linkedin:{i}",
        }
        for i in range(8)
    ]
    candidates.extend(
        {
            "candidate_id": f"github-source:{i}",
            "lane": "C",
            "organization": "GitHub Repo Intel",
            "title": f"GitHub repository intelligence {i}",
            "workplace_type": "NOT_APPLICABLE",
            "location_display": "GitHub source-intel; delivery model not applicable",
            "fit_score": 0.58,
            "relocation_required": False,
            "clearance_required": False,
            "source_provider": "github_repo_intelligence",
            "source_receipt_id": f"receipt:github:{i}",
        }
        for i in range(2)
    )
    fixture = tmp_path / "candidates.json"
    fixture.write_text(json.dumps({"candidates": candidates}), encoding="utf-8")
    out = tmp_path / "ranking"

    result = runner.invoke(app, ["rank", "--input", str(fixture), "--limit", "8", "--out", str(out)])

    assert result.exit_code == 0, result.output
    source_intel = json.loads((out / "source-intel-shortlist.json").read_text(encoding="utf-8"))
    source_ids = [row["candidate_id"] for row in source_intel]
    assert len(source_intel) == 8
    assert "github-source:0" in source_ids
    assert "github-source:1" in source_ids
    assert sum(row["source_provider"] == "github_repo_intelligence" for row in source_intel) == 2
    assert sum(row["source_provider"] == "ops_linkedin_authorized_read_only" for row in source_intel) == 6


